<script setup>
import { onMounted, ref } from 'vue'
import { useManagementStore } from '../stores/management'
const store = useManagementStore(), form = ref({ courseId: '', courseName: '' }), message = ref(''), error = ref(''), busy = ref(false)
onMounted(() => store.loadCourses().catch(e => error.value = e.message))
async function submit() { message.value=''; error.value=''; busy.value=true; try { await store.addCourse({ ...form.value }); form.value={ courseId:'', courseName:'' }; message.value='Course added successfully.' } catch(e) { error.value=e.message } finally { busy.value=false } }
async function remove(course) { if (!confirm(`Delete ${course.courseId} — ${course.courseName}? Related enrollments will also be removed.`)) return; try { await store.deleteCourse(course._id); message.value='Course deleted.' } catch(e) { error.value=e.message } }
</script>
<template><section class="page-heading"><div><div class="eyebrow">DIRECTORY / ACADEMICS</div><h1>Course management</h1><p class="subtitle">Manage course offerings and maintain the catalog used for student enrollment.</p></div><div class="heading-chip"><span class="chip-icon">▦</span><span><strong>{{ store.courses.length }} courses</strong><small>COURSE CATALOG</small></span></div></section>
<div v-if="message" class="alert success" role="status">✓ {{ message }}</div><div v-if="error" class="alert error" role="alert">{{ error }}</div><div class="two-column course-layout"><section class="panel form-panel"><div class="panel-heading"><div><span class="section-kicker">NEW COURSE</span><h2>Add a course</h2></div><span class="panel-icon">＋</span></div><form @submit.prevent="submit"><label>Course ID<input v-model.trim="form.courseId" required maxlength="30" placeholder="e.g. CIS 3339"/></label><label>Course name<input v-model.trim="form.courseName" required maxlength="150" placeholder="Enterprise Applications Development"/></label><button class="primary-button" :disabled="busy">{{ busy ? 'Saving…' : 'Add course' }} <span>→</span></button></form><p class="form-note">Course IDs must be unique across the catalog.</p></section><section class="panel list-panel"><div class="panel-heading"><div><span class="section-kicker">AVAILABLE COURSES</span><h2>Course catalog</h2></div><span class="count-pill">{{ store.courses.length }} COURSES</span></div><div v-if="!store.courses.length" class="empty-state"><span class="empty-icon">▦</span><strong>No courses yet</strong><small>Add a course to get started.</small></div><div v-else class="course-list"><article v-for="(course, index) in store.courses" :key="course._id" class="course-item"><span class="course-index">{{ String(index+1).padStart(2,'0') }}</span><div class="course-info"><strong>{{ course.courseId }}</strong><span>{{ course.courseName }}</span></div><button class="icon-button danger-text" :aria-label="`Delete ${course.courseId}`" @click="remove(course)">×</button></article></div></section></div></template>
